with target as(select * from public.works where id=any(array[1611,3272,3514,4947,2989,3188,3273,3475,4935,1443]::bigint[]) or open_library_id=any(array['OL1905374W','OL1966480W','OL32045W','OL497179W','OL134853W','OL12302586W','OL1725868W','OL79323W','OL17356815W','OL15343361W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['liefdeenschaduw','deamorydesombra','hetverhaalvanonzevoorouders','theancestorstale','wilt','spiegelvandeziel','theface','hetzaadvangisteren','seedsofyesterday','dedwergen','diezwerge','deoorlogheeftgeenvrouwengezicht','valsspel','dealbreaker','ikmisje','missingyou','taaliszegmaarechtmijnding']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['liefdeenschaduw','deamorydesombra','hetverhaalvanonzevoorouders','theancestorstale','wilt','spiegelvandeziel','theface','hetzaadvangisteren','seedsofyesterday','dedwergen','diezwerge','deoorlogheeftgeenvrouwengezicht','valsspel','dealbreaker','ikmisje','missingyou','taaliszegmaarechtmijnding']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL228079A','OL236174A','OL27871A','OL33088A','OL22019A','OL3173527A','OL198376A','OL39821A','OL6823890A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['isabelallende','isabelallendellona','isabelleallende','iallende','richarddawkins','rdawkins','dawkinsrichard','tomsharpe','thomasridleysharpe','deankoontz','aaronwolfepseud','briancoffeypseud','davidaxtonpseud','vcandrews','cleovirginiaandrews','virginiacandrews','andrewsvcandrews','markusheitz','salexievich','svetlanaaleksandroff','svetlanaaleksandrovnaaleksievich','harlancoben','cobenharlan','pauliencornelisse']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL47264055M','OL24778188M','OL47246903M','OL28239362M','OL32360500M','OL32985884M','OL60495117M','OL47082998M','OL32361557M','OL24334237M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789028415089','9789046803363','9789067661294','9789024547791','9789044924824','9789024559923','9789023499527','9789022566206','9789022565186','9789025430498']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
